This is a proof of concept for jitclass caching - it can be done and does kind of work. There are almost certainly bugs still living in here, but if you need it, this is a starting point.
```python
import numba as nb
from numba.core.caching import Cache
from numba.core import environment
from numba.core.decorators import njit
from functools import wraps
from numba.experimental.jitclass import boxing
from numba.core.dispatcher import _DispatcherBase
import inspect

"""
Numba jitclass caching support hack


DO NOT USE IN PRODUCTION
DO NOT EXPECT TO CONTINUE TO WORK
DO NOT CONSIDER DEEPLY (DARK MAGIC)
"""

def _generate_method(name, func):
    source = boxing._method_code_template.format(method=name)
    glbls = {}
    exec(source, glbls)
    method = glbls['method']
    method.__code__ = method.__code__.replace(co_name=func.__code__.co_name, co_filename=func.__code__.co_filename, co_qualname=func.__code__.co_qualname,co_firstlineno=func.__code__.co_firstlineno)
    method.__qualname__ = func.__qualname__
    method.__name__ = func.__name__
    method = njit(method,cache=True)

    @wraps(func)
    def wrapper(*args, **kwargs):
        return method(*args, **kwargs)

    return wrapper

boxing._generate_method = _generate_method

def make_from_fndesc(orig):
    @classmethod
    def from_fndesc(_, fndesc):
        ret = orig(fndesc)
        if not ret.globals.get('__name__'):
            try:
                ret.globals['__name__'] = inspect.getmodule(fndesc.typemap['__numba_self_'].methods['__init__']).__name__
            except:
                pass
        return ret
    return from_fndesc



environment.Environment.from_fndesc =  make_from_fndesc(environment.Environment.from_fndesc)

def transform_sig_item(item):
    if isinstance(item, nb.core.types.misc.ClassInstanceType):
        return item.class_type.instance_type.classname
    elif isinstance(item, (tuple, nb.types.UniTuple, nb.types.Tuple)):
        return tuple(transform_sig_item(x) for x in item)
    elif isinstance(item, (nb.types.ListType, nb.types.List)):
        return nb.types.ListType(transform_sig_item(item.dtype))
    return item

def give_new_load_overload(orig):
    def wrap(self,sig, target_context):
        newsig = transform_sig_item(sig)
        print("LOAD OVERLOAD", newsig)
        ret = orig(self, newsig, target_context)
        if ret is not None:
            ret.library.origsig = sig
        return ret
    return wrap

def give_new_save_overload(orig):
    def wrap(self,sig, data):
        newsig = transform_sig_item(sig)
        print("SAVE OVERLOAD", newsig)
        return orig(self, newsig, data)
    return wrap

Cache.load_overload = give_new_load_overload(Cache.load_overload)
Cache.save_overload = give_new_save_overload(Cache.save_overload)


def add_overload(self, cres):
    if hasattr(cres.library,'origsig'):
        args = cres.library.origsig # yes it totally works.
    else:
        args = tuple(cres.signature.args)
    sig = [a._code for a in args]
    self._insert(sig, cres.entry_point, cres.objectmode)
    #print(args)
    self.overloads[args] = cres


_DispatcherBase.add_overload = add_overload

class Potato:
    x: int
    y: int

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def add(self, other):
        return self.x + other

    def add2(self, other):
        return self.y + other


@nb.experimental.jitclass
class Thing1:
    def __init__(self):
        pass

    def val(self):
        return 5

@nb.experimental.jitclass
class Thing2:
    def __init__(self):
        pass

    def val(self):
        return 6


@nb.njit(cache=True)
def thingsolver(thing):
    return -thing.val()


Pjc = nb.experimental.jitclass(Potato)

pto = Pjc(1,2)
pto2 = Pjc(6,6)
print(pto.add(1))

print(pto.add(1))
print("#"*25)
print(pto.add2(1))
pto.x = 5
print("#"*25)
print(pto.add(1))
print("#"*25)
print(pto2.add(5))
print(pto2.add(6))
print(pto2.add2(7))

th1 = Thing1()
th2 = Thing2()
print(thingsolver(th1))
print(thingsolver(th1))
print(thingsolver(th2))
print(thingsolver(th2))

```

