## Description

When using the `typescript-axios` generator, if an OpenAPI schema property has an `anyOf` with a `title` attribute, the generator creates a separate empty interface based on that title instead of generating a proper union type.

## OpenAPI Specification

```json
{
    "openapi": "3.1.0",
    "info": {
        "title": "Demo",
        "version": "0.1.0"
    },
    "paths": {
        "/users": {
            "get": {
                "summary": "Read Root",
                "operationId": "read_root_users_get",
                "parameters": [
                    {
                        "name": "expand",
                        "in": "query",
                        "required": false,
                        "schema": {
                            "type": "boolean",
                            "default": false,
                            "title": "Expand"
                        }
                    }
                ],
                "responses": {
                    "200": {
                        "description": "Successful Response",
                        "content": {
                            "application/json": {
                                "schema": {
                                    "type": "array",
                                    "items": {
                                        "$ref": "#/components/schemas/UserResponse"
                                    },
                                    "title": "Response Read Root Users Get"
                                }
                            }
                        }
                    }
                }
            }
        }
    },
    "components": {
        "schemas": {
            "Trip": {
                "properties": {
                    "id": {
                        "type": "string",
                        "title": "Id"
                    },
                    "destination": {
                        "type": "string",
                        "title": "Destination"
                    },
                    "date": {
                        "type": "string",
                        "title": "Date"
                    }
                },
                "type": "object",
                "required": [
                    "id",
                    "destination",
                    "date"
                ],
                "title": "Trip"
            },
            "UserResponse": {
                "properties": {
                    "id": {
                        "type": "string",
                        "title": "Id"
                    },
                    "booked_trips": {
                        "anyOf": [
                            {
                                "items": {
                                    "type": "string"
                                },
                                "type": "array"
                            },
                            {
                                "items": {
                                    "$ref": "#/components/schemas/Trip"
                                },
                                "type": "array"
                            }
                        ],
                        "title": "Booked Trips"
                    }
                },
                "type": "object",
                "required": [
                    "id",
                    "booked_trips"
                ],
                "title": "UserResponse"
            }
        }
    }
}
```

