### OpenTofu Version

```shell
1.12.3
```

### The problem in your OpenTofu project

Hi there, I'm not sure if anyone has already proposed similar feature. I skimmed through open issues, but haven't found matching one.

It would drastically simplify refactoring if I could use `for_each` in `moved` blocks, just like I can use it today in the `import` blocks.

### Attempted Solutions

Currently the only viable way is to use opentofu CLI and write bash loops.

### Proposal

Let's say I want to change for_each indexes in addition to moving state:
```terraform
variable "old_key_segment" {
  type = string
}
variable "new_key_segment" {
  type = string
}
variable "aks_cluster" {
  type = object({
    id              = string
    oidc_issuer_url = string
  })
  nullable = false
}
variable "aks_workload_identities" {
  type = list(object({
    identity_name = string
    azure_federated_credential = object({
      user_assigned_identity_id = string
      name                      = string
      subject                   = string
    })
    service_account = optional(object({
      name                              = string
      namespace                         = string
      azure_workload_identity_client_id = string
      annotations                       = optional(map(string))
      labels                            = optional(map(string))
    }))
  }))
  default = []
}

moved {
  # ⚠️ 👇🏼 Would like to be able to do for_each like this👇🏼
  for_each = {
    for wi_k, wi in var.aks_workload_identities : wi_k => {
      old_key = "${var.old_key_segment}${wi.identity_name}"
      new_key = "${var.new_key_segment}:${wi.identity_name}:${wi.azure_federated_credential.name}"
    }
  }

  from = azurerm_federated_identity_credential.these[each.value.old_key]
  to   = module.workload_identities[each.value.new_key].azurerm_federated_identity_credential.this
}

# FROM 👇🏼
# resource "azurerm_federated_identity_credential" "these" {
#   for_each = { for wi in var.aks_workload_identities : ${var.old_key_segment}${wi.identity_name}} => wi
#   ... old inputs ...
# }

# TO 👇🏼
module "workload_identities" {
  source = "./workload-identity"

  for_each = { for wi in var.aks_workload_identities : "${var.new_key_segment}:${wi.identity_name}:${wi.azure_federated_credential.name}" => wi }

  aks_cluster_oidc_issuer_url = var.aks_cluster.oidc_issuer_url
  service_account             = each.value.service_account
  azure_federated_credential  = each.value.azure_federated_credential
}
```

